\label{defn:props}
    Let $(Q,\triangleleft)$ be a rack.
    \begin{itemize}
        \item We say that $Q$ is a \emph{quandle} if $x\triangleleft x=x$ for all $x\in Q$. A subset $Q'\subseteq Q$ is called a \emph{subquandle} of $Q$ if $R_x(Q')=Q'$ for all $x\in Q'$.\footnote{Some authors only require that $R_x(Q')\subseteq Q$ in their definitions of subquandles. However, unless $Q'$ is finite, this weaker condition does not always guarantee that $Q'$ is a quandle; see \cite{kamada}*{Sec.\ 2} for counterexamples.}
        \item We say that $Q$ is \emph{semi-latin} or \emph{(left-)cancellative} (resp.\ \emph{latin}) if every left-multiplication map $L_x$ is injective (resp.\ bijective).
        \item We say that $Q$ is \emph{medial}, \emph{abelian}, or \emph{entropic} if $\triangleleft\colon Q\times Q\to Q$ is a rack homomorphism, where $Q\times Q$ is equipped with the product rack structure.
        \item We say that $Q$ is \emph{inert} if there exist a nonempty finite subset $X\subseteq Q$ and two distinct elements $a,b\in Q$ such that $R_a(X)=R_b(X)$.
        \item We say that $Q$ is a \emph{unique product rack} or \emph{u.p.-rack} if, given any two nonempty finite subsets $Y,Z\subseteq Q$, there exists an element $x\in Q$ that can be uniquely expressed in the form $x=y\triangleleft z$ with $y\in Y$ and $z\in Z$.
        \item We say that $Q$ is \emph{faithful} if $R_x\neq R_y$ in $\operatorname{Aut}(Q)$ whenever $x\neq y$ in $Q$.
    \end{itemize}

Let $Q$ be a rack.
    \begin{itemize}
        \item Define an equivalence relation (in fact a congruence relation) $\lambda_Q$ on $Q$ by identifying $x\lambda_Qy$ if and only if $R_x=R_y$ in $\operatorname{Aut}(Q)$. We call $\lambda_Q$ the \emph{Cayley kernel} or \emph{retraction relation} of $Q$.
        \item The \emph{retract} of $Q$ is the quotient rack $\operatorname{Ret}(Q)\coloneq Q/\lambda_Q$.
        \item Let $n\geq 0$. The \emph{$n$-fold retract} of $Q$ is the rack $\operatorname{Ret}^n(Q)\coloneq\underbrace{\operatorname{Ret}(\dots(\operatorname{Ret}}_{n\text{ times}}(Q))\dots)$. 
    \end{itemize}

\label{prop:covering}
    Let $k$ be a commutative ring, and let $\pi\colon Q\twoheadrightarrow Q'$ be a covering map of quandles. Then:
    \begin{enumerate}[(i)]
        \item For all $u\in k[Q]$ and $v\in \ker k[\pi]$, we have $u*v=0$. In particular, $\ker k[\pi]$ contains no nonzero idempotent elements.
        \item If every nonzero idempotent element $u'\in k[Q']$ satisfies $\varepsilon(u')=1$, then every nonzero idempotent element $u\in k[Q]$ satisfies $\varepsilon(u)=1$.
    \end{enumerate}

\label{prop:inert-embed}
    Let $Q$ be a semi-latin medial quandle. Then:
    \begin{enumerate}[(i)]
        \item $Q$ embeds into a latin Alexander quandle $\operatorname{Alex}(A,\varphi)$.
        \item If $Q$ is not inert, then $A$ can be chosen to be torsion-free as an abelian group. 
    \end{enumerate}

\label{prop:alex-retract}
    Let $Q\coloneq\operatorname{Alex}(A,\varphi)$ be an Alexander quandle, and let $\psi\coloneq\mathrm{id}-\varphi$. Then: 
    \begin{enumerate}[(i)]
        \item For all $n\geq 0$, $\operatorname{Alex}(\psi^n(A),\varphi)$ is an Alexander quandle that is isomorphic to $\operatorname{Ret}^n(Q)$.
        \item If $A$ is finite, then $Q'\coloneq\operatorname{Alex}(\operatorname{im}^\infty\psi,\varphi)$ is a latin subquandle of $Q$, and $\operatorname{Ret}^n(Q)\cong Q'$ for all sufficiently large $n\gg0$.
    \end{enumerate}

\label{lem:three}
    Let $Q\coloneq\operatorname{Alex}(A,\varphi)$ be a finite latin Alexander quandle. 
    If $u\in k[Q]$ is idempotent, then $\hat u(\operatorname{supp}\hat u)\subset k[\zeta_n]^\times$.

\label{lem:primes}
    Let $k$ be an integral domain of characteristic $0$, let $Q\coloneq\operatorname{Alex}(A,\varphi)$ be a finite latin Alexander quandle, and let $u\in k[Q]$ be an idempotent element. 
    Let $\chi\in\operatorname{supp}\hat u$, and suppose that $\chi$ has order $\ell>1$ in $\hat A$. Let $p$ be a prime dividing $\ell$, write $\ell=p^am$ with $p\nmid m$, and write $\chi=\chi_p\chi_m$, where $\chi_p$ and $\chi_m$ have orders $p^a$ and $m$ in $\langle\chi\rangle\leq\hat A$, respectively. If $p\notin k^\times$, then $\chi_m\in\operatorname{supp}\hat u$.
